def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_opp += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    scarcity = 1.0 - supply_ratio

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if scarcity > 0.6:
        danger += 1
    if urgent_opp >= 2:
        danger += 1

    if danger >= 5:
        target = max(62.0, highest_prev + 6.0)
    elif danger >= 3:
        target = max(42.0 + 10.0 * scarcity, avg_prev + 3.0)
    else:
        if supply >= 22:
            target = 16.0 + 6.0 * scarcity
        elif supply >= 19:
            target = 22.0 + 10.0 * scarcity
        else:
            target = 30.0 + 12.0 * scarcity
        if highest_prev > 0:
            target = max(target, min(highest_prev + 1.5, 58.0))

    if rich_opp >= 2 and scarcity > 0.5 and danger >= 2:
        target += 6.0

    if day >= 8 and hp > 5 and no_water_days == 0:
        target *= 0.9

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 20.0
    max_affordable = max(0.0, budget - reserve_floor)
    if danger >= 4:
        max_affordable = budget

    bid = min(target, max_affordable)

    if danger >= 5:
        bid = min(max(bid, 68.0), budget)
    elif danger >= 3:
        bid = min(max(bid, 45.0), budget)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

